(()=>{const root=document.querySelector('.cp-archive');if(!root)return;const cards=[...root.querySelectorAll('.cp-archive-item')],filters=[...root.querySelectorAll('[data-filter]')],input=root.querySelector('[data-archive-query]'),status=root.querySelector('[data-archive-status]'),empty=root.querySelector('[data-archive-empty]'),toggle=root.querySelector('.cp-more');const it=document.documentElement.lang==='it';let category='all',expanded=true;const normal=s=>s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function render(){const query=normal(input.value.trim());const matching=cards.filter(c=>(category==='all'||c.dataset.category===category)&&normal(c.textContent).includes(query));for(const c of cards){const index=matching.indexOf(c);c.hidden=index<0||(!expanded&&!query&&index>=8);}for(const b of filters){const active=b.dataset.filter===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));}const shown=matching.filter(c=>!c.hidden).length;status.textContent=it?shown+' di '+matching.length+' voci / '+cards.length+' in archivio':shown+' of '+matching.length+' entries / '+cards.length+' in the archive';empty.hidden=matching.length>0;toggle.hidden=!!query||matching.length<=8;toggle.textContent=(expanded?toggle.dataset.expanded:toggle.dataset.collapsed)+(expanded?' ↑':' ↓');toggle.setAttribute('aria-expanded',String(expanded));}for(const b of filters)b.addEventListener('click',()=>{category=b.dataset.filter;expanded=true;render();});input.addEventListener('input',render);input.addEventListener('keydown',event=>{if(event.key==='Escape'){input.value='';render();}});toggle.addEventListener('click',()=>{expanded=!expanded;render();});render();})();